import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    prices = [int(next(it)) for _ in range(n)]

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u = int(next(it)) - 1  # 0-indexed
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)

    min_sum = float('inf')

    # Check for triangles
    for i in range(n):
        for j in adj[i]:
            if i < j:  # Avoid duplicate checks
                for k in adj[i]:
                    if j < k and k in adj[j]:
                        # Triangle found: i, j, k
                        total = prices[i] + prices[j] + prices[k]
                        if total < min_sum:
                            min_sum = total

    print(min_sum if min_sum != float('inf') else -1)

if __name__ == "__main__":
    solve()
"}

