def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    # Create a Fenwick Tree where each position stores the count of a particular number
    # We need to handle values up to n
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, index, value):
            # Add 'value' to position 'index'
            while index <= self.n:
                self.tree[index] += value
                index += index & -index

        def query(self, index):
            # Sum from position 1 to 'index'
            res = 0
            while index > 0:
                res += self.tree[index]
                index -= index & -index
            return res

    # Build the Fenwick Tree
    ft = FenwickTree(n)
    for num in a:
        ft.update(num, 1)

    # Process queries
    for _ in range(m):
        l, r = map(int, input().split())

        # Count how many numbers x satisfy x appears exactly x times in [l, r]
        ans = 0
        for x in range(1, n + 1):
            count = ft.query(r) - ft.query(l - 1)
            if count == x:
                ans += 1

        print(ans)

solve()
