    # We need to handle values up to n
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, index, value):
            # Add 'value' to position 'index'
            while index <= self.n:
                self.tree[index] += value
                index += index & -index

        def query(self, index):
            # Sum from position 1 to 'index'
            res = 0
            while index > 0:
                res += self.tree[index]
                index -= index & -index
            return res

