def f(x_digits, y_digits):
    """Calculate f(x, y) where x and y are lists of digits (least significant first)."""
    p = len(x_digits)
    q = len(y_digits)

    if p >= q:
        # Start with extra digits from x
        result = x_digits[:p-q]

        # Alternate remaining digits
        for i in range(q):
            result.append(x_digits[i])
            result.append(y_digits[i])
    else:
        # Start with extra digits from y
        result = y_digits[:q-p]

        # Alternate remaining digits
        for i in range(p):
            result.append(x_digits[i])
            result.append(y_digits[i])

    # Convert result to integer (reverse back to most significant first)
    if not result:
        return 0
    return int(''.join(map(str, reversed(result))))

def solve():
    n = int(input())
    line = input().strip()
    a = list(map(int, line.split()))

    # Convert each number to its digits (least significant first)
    num_digits = [
        [int(d) for d in str(num)][::-1]  # Reverse to least significant first
        for num in a
    ]

    total = 0
    mod = 998244353

    for i in range(n):
        for j in range(n):
            total = (total + f(num_digits[i], num_digits[j])) % mod

    print(total)

solve()
