{"code": "
import sys
import math

def is_prime(n):
    """Check if a number is prime"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = int(math.sqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    numbers = list(map(int, data[1:n+1]))

    for x in numbers:
        # Check if x is a perfect square
        sqrt_x = int(math.isqrt(x))  # Using math.isqrt for integer square root
        if sqrt_x * sqrt_x == x:
            # Check if the square root is prime
            if is_prime(sqrt_x):
                print("YES")
            else:
                print("NO")
        else:
            print("NO")

if __name__ == "__main__":
    solve()
"}

