# Function to check if two numbers are co-prime
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def co_prime(a, b):
    return gcd(a, b) == 1

# Find a number that is co-prime with both a and b
def find_insert_number(a, b):
    # Try numbers from 1 to 100 to find one that works
    for x in range(1, 100):
        if co_prime(a, x) and co_prime(b, x):
            return x
    return 10**9 + 1  # Should never reach here

result = [arr[0]]
insert_count = 0

for i in range(1, n):
    prev = arr[i-1]
    curr = arr[i]

    # Check if adjacent elements are co-prime
    if not co_prime(prev, curr):
        # Find a number to insert
        insert_num = find_insert_number(prev, curr)

        # Insert the number
        result.append(insert_num)
        insert_count += 1

    # Add the current element
    result.append(curr)

if insert_count == 0:
    for num in result:
        print(num)
else:
    print(insert_count)
    print(' '.join(map(str, result)))
