import sys
import bisect

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n, m = int(next(it)), int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Map each number to its sorted list of positions
    positions = {}
    for idx, val in enumerate(a, start=1):
        if val not in positions:
            positions[val] = []
        positions[val].append(idx)

    out_lines = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))
        answer = 0
        L = r - l + 1

        # Check all numbers <= L that appear in the array
        for x in positions:
            if x <= L:
                pos_list = positions[x]
                left = bisect.bisect_left(pos_list, l)
                right_idx = bisect.bisect_right(pos_list, r)
                count = right_idx - left
                if count == x:
                    answer += 1

        out_lines.append(str(answer))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

