        candies[a].append(b)

    def distance(s, d):
        # Distance from station s to station d on a circular track of n stations
        clockwise = (d - s) % n
        counter_clockwise = (s - d) % n
        return min(clockwise, counter_clockwise)

    result = []
    for starting_station in range(1, n + 1):
        max_time = 0

        # For each station, calculate the maximum time needed to deliver all candies
        for station in range(1, n + 1):
            if candies[station]:
                # Time for the first candy from this station
                # Time = distance(starting_station, station) + distance(station, b)
                first_candy_time = distance(starting_station, station) + distance(station, candies[station][0])

                # Time for subsequent candies from this station
                # Each subsequent candy takes n more seconds (to wait for the train to come back)
                for idx in range(1, len(candies[station])):
                    first_candy_time += n

                max_time = max(max_time, first_candy_time)

        result.append(max_time)

    print(' '.join(map(str, result)))

