{"code": "
import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    edges = set()

    idx = 2
    adj = defaultdict(list)
    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx+1])
        edges.add((min(a, b), max(a, b)))
        adj[a].append(b)
        adj[b].append(a)
        idx += 2

    visited = [False] * (n + 1)

    def is_complete(component):
        component_set = set(component)
        for u in component:
            for v in component:
                if u == v:
                    continue
                if (min(u, v), max(u, v)) not in edges:
                    return False
        return True

    for node in range(1, n + 1):
        if not visited[node]:
            # BFS to find connected component
            q = deque([node])
            visited[node] = True
            component = [node]
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        component.append(v)
                        q.append(v)

            if not is_complete(component):
                print("NO")
                return

    print("YES")

if __name__ == "__main__":
    solve()
"}

