# Function to calculate students needed for given t
def students_needed(t):
    if t >= max(i + a[i] for i in range(n)):
        # We can finish all piles at time t by assigning students
        # Each pile i needs (i + a[i] - t) students
        return sum(max(0, i + a[i] - t) for i in range(n))
    else:
        # If t < max(i + a[i]), we need more time
        # But we don't have enough students to complete any pile on time
        # Actually, we can try to finish all piles at time t by assigning
        # the extra students to help reduce the time
        return sum(max(0, i + a[i] - t) for i in range(n))

answer = right
while left <= right:
    mid = (left + right) // 2
    needed = students_needed(mid)
    if needed <= m:
        answer = mid
        right = mid - 1
    else:
        left = mid + 1

print(answer)
