    def distance(u, v):
        # BFS to find shortest path
        visited = {}
        queue = [u]
        visited[u] = 0

        while queue:
            current = queue.pop(0)
            if current == v:
                return visited[current]
            for neighbor in tree[current]:
                if neighbor not in visited:
                    visited[neighbor] = visited[current] + 1
                    queue.append(neighbor)

    q = int(input())

    for _ in range(q):
        x, y, a, b, k = map(int, input().split())

        # Calculate original shortest path
        original_shortest = distance(a, b)

        # Calculate shortest path with new edge
        path1 = distance(a, x) + 1 + distance(y, b)
        path2 = distance(a, y) + 1 + distance(x, b)

        # Check each candidate shortest path
        possible = []
        if k >= original_shortest:
            possible.append(original_shortest)
        if k >= path1:
            possible.append(path1)
        if k >= path2:
            possible.append(path2)

        # Check if any of these paths can reach k by going around the cycle
        cycle = distance(x, y) + 1

