import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    lines = data
    n, m = map(int, lines[0].split())

    # Group participants by region
    regions = {}
    for line in lines[1:n+1]:
        parts = line.split()
        surname = parts[0]
        region = int(parts[1])
        score = int(parts[2])

        if region not in regions:
            regions[region] = []
        regions[region].append((surname, score))

    # Process each region
