# Try all possible distributions of candies
for candies_dist in itertools.product(range(min(k, 10) + 1), repeat=n):
    if sum(candies_dist) > k:
        continue

    # Calculate new loyalties
    loyalties = [(b, min(l + 10 * candies, 100)) for (b, l), candies in zip(senators, candies_dist)]

    # Calculate probability of passing by vote
    vote_prob = 0.0

    # For each possible subset of yes votes, calculate probability
    for yes_votes in range(n + 1):
        # Calculate probability of exactly yes_votes yes votes
        prob = 1.0
        for i in range(n):
            if yes_votes == 0:
                prob *= (1 - loyalties[i][1] / 100)
            elif yes_votes == n:
                prob *= loyalties[i][1] / 100
            else:
                if i < yes_votes:
                    prob *= loyalties[i][1] / 100
                else:
                    prob *= (1 - loyalties[i][1] / 100)

        # If we pass by vote
        if yes_votes > n / 2:
            vote_prob += prob

    # If we pass by vote, probability is just vote_prob
    if vote_prob >= 1.0 - 1e-9:
        max_prob = max(max_prob, vote_prob)
