from collections import defaultdict

def process_url(url):
    # Split on '://' to get the part after
    parts = url.split('://', 1)
    if len(parts) < 2:
        return None  # invalid URL, but problem says it's valid
    rest = parts[1]

    # Split on '/' to get hostname and path
    if '/' in rest:
        hostname, path = rest.split('/', 1)
    else:
        hostname, path = rest, ''

    # Add path to set (empty path is just '/')
    if path == '' and '/' in rest:
        path = '/'

    return hostname, path

def main():
    n = int(input())
    hostname_to_paths = defaultdict(set)

    for _ in range(n):
        url = input().strip()
        hostname, path = process_url(url)
        if hostname is None or path is None:
            continue

        hostname_to_paths[hostname].add(path)

    # Group hostnames by their set of paths
    groups = defaultdict(list)
    for hostname, paths in hostname_to_paths.items():
        groups[frozenset(paths)].append(hostname)

    # Output results
    result = []
    for paths, hostnames in groups.items():
        if len(hostnames) > 1:
            result.append(" ".join(hostnames))

    print(len(result))
    for line in result:
        print(line)

if __name__ == "__main__":
    main()
