        action = parts[0]
        price = int(parts[1])

        if action == "ADD":
            new_states = []

            for state in states:
                best_buy, best_sell, ways = state

                # Try assigning BUY
                if not buy_orders or price > max(buy_orders):
                    # p could be the new best BUY
                    if not sell_orders or price < min(sell_orders):
                        # Valid as BUY
                        buy_orders.add(price)
