                        if not sell_orders or price < min(sell_orders):
                            # Both valid, multiply by 2
                            new_ways = (ways * 2) % MOD
                        else:
                            new_ways = ways
                        new_states.append((price, best_sell, new_ways))
                        buy_orders.remove(price)

