                        if not buy_orders or price > max(buy_orders):
                            # Both valid, multiply by 2
                            new_ways = (ways * 2) % MOD
                        else:
                            new_ways = ways
                        new_states.append((best_buy, price, new_ways))
                        sell_orders.remove(price)

            if not states:
                # No previous state, we have two options for first order
                # Try BUY
                if not sell_orders or price < min(sell_orders):
                    # First order as BUY
                    if not sell_orders or price < min(sell_orders):
                        new_ways = 2
                    else:
                        new_ways = 1
                    new_states.append((price, None, new_ways))

