import itertools

def solve():
    n, k, A = map(int, input().split())
    senators = []
    for _ in range(n):
        b, l = map(int, input().split())
        senators.append((b, l))

    max_prob = 0.0

    # Try all possible distributions of candies
    for candies in itertools.product(range(k + 1), repeat=n):
        if sum(candies) > k:
            continue

        # Apply candies
        for i in range(n):
            senators[i] = (senators[i][0], min(senators[i][1] + candies[i], 100))

        # Simulate all possible voting outcomes
        prob = 0.0
        for vote in itertools.product([0, 1], repeat=n):
            # Calculate probability of this voting outcome
            outcome_prob = 1.0
            for i in range(n):
                if vote[i] == 1:
                    # Vote yes
                    outcome_prob *= senators[i][1] / 100.0
                else:
                    # Vote no
                    outcome_prob *= (100 - senators[i][1]) / 100.0

            # Check if proposal is approved
            if sum(vote) > n // 2:
                # Direct approval
                prob += outcome_prob
            else:
                # Need to appeal - calculate probability of killing all no voters
                appeal_prob = 1.0
                for i in range(n):
                    if vote[i] == 0:
                        appeal_prob *= A / (A + senators[i][0])
                prob += outcome_prob * appeal_prob

        max_prob = max(max_prob, prob)

    print(f"{max_prob:.10f}")

solve()
