def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, a, b, da, db = map(int, input().split())

        # We need to compute the distance between a and b
        # For simplicity, I'll use BFS

        from collections import defaultdict, deque

        graph = defaultdict(list)
        for _ in range(n-1):
            u, v = map(int, input().split())
            graph[u-1].append(v-1)
            graph[v-1].append(u-1)

        # BFS to find distance between a and b
        def bfs(start, end):
            if start == end:
                return 0
            visited = [False] * n
            queue = deque([(start, 0)])
            visited[start] = True

            while queue:
                node, dist = queue.popleft()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        if neighbor == end:
                            return dist + 1
                        queue.append((neighbor, dist + 1))
            return float('inf')

        distance = bfs(a-1, b-1)

        if da >= db or distance <= da:
            results.append("Alice")
        else:
