import sys
import math

def compute_spf(max_n):
    """Compute smallest prime factors (spf) for numbers up to max_n"""
    spf = list(range(max_n + 1))  # spf[i] is smallest prime factor of i
    for i in range(2, int(math.isqrt(max_n)) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_n + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def prime_factors(x, spf):
    """Get prime factors of x using spf"""
    factors = set()
    while x > 1:
        p = spf[x]
        factors.add(p)
        while x % p == 0:
            x //= p
    return factors

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Precompute smallest prime factors
    max_num = n
    spf = compute_spf(max_num)

    # Map from prime factor to set of collider indices using this factor
    prime_to_colliders = {}

    # Set of activated colliders
    activated = set()

    for _ in range(m):
        req = next(it)
        i = int(next(it))

        if req == "+":
            # Check if already activated
            if i in activated:
                print("Already on")
                continue

            # Check prime factors for conflicts
            conflict = None
            factors = prime_factors(i, spf)
            for p in factors:
                if p in prime_to_colliders:
                    # There's a collider with this prime factor
                    collider = next(iter(prime_to_colliders[p]))  # pick any
                    conflict = collider
                    break

            if conflict is not None:
                print(f"Conflict with {conflict}")
            else:
                activated.add(i)
                for p in factors:
                    prime_to_colliders.setdefault(p, set()).add(i)
                print("Success")
        else:  # req == "-"
            if i not in activated:
                print("Already off")
            else:
                activated.remove(i)
                factors = prime_factors(i, spf)
                for p in factors:
                    prime_to_colliders[p].discard(i)
                    if not prime_to_colliders[p]:
                        del prime_to_colliders[p]
                print("Success")

if __name__ == "__main__":
    main()
