import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+m]))

    # dp[i][j] = number of ways to be at position j after i moves without being at any forbidden position
    dp = [[0] * (n + 1) for _ in range(m + 2)]

    # Initial state: before any move, we're at some position
    for x in range(1, n + 1):
        dp[0][x] = 1

    # After each move
    for move in range(1, m + 1):
        forbidden_pos = a[move - 1]
        for pos in range(1, n + 1):
            # If we're at position pos at step move, check if it's forbidden
            if pos == forbidden_pos:
                continue

            # From where can we move to pos?
            if pos - 1 >= 1:
                dp[move][pos] += dp[move - 1][pos - 1]
            dp[move][pos] += dp[move - 1][pos]
            if pos + 1 <= n:
                dp[move][pos] += dp[move - 1][pos + 1]

    # After m moves, one more move (no constraint at the end)
    for pos in range(1, n + 1):
        # From where can we move to pos?
        if pos - 1 >= 1:
            dp[m + 1][pos] += dp[m][pos - 1]
        dp[m + 1][pos] += dp[m][pos]
        if pos + 1 <= n:
            dp[m + 1][pos] += dp[m][pos + 1]

    # Count total scenarios
    total = 0
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            total += dp[m + 1][y]

    print(total)

if __name__ == "__main__":
    solve()
