# dp[i][j] = length of LCS between substrings a[i:] and b[j:]
dp = [[0] * (m + 1) for _ in range(n + 1)]

def lcs(s1, s2):
    n1, m1 = len(s1), len(s2)
    dp_lcs = [[0] * (m1 + 1) for _ in range(n1 + 1)]
    for i in range(1, n1 + 1):
        for j in range(1, m1 + 1):
            if s1[i-1] == s2[j-1]:
                dp_lcs[i][j] = dp_lcs[i-1][j-1] + 1
            else:
                dp_lcs[i][j] = max(dp_lcs[i-1][j], dp_lcs[i][j-1])
    return dp_lcs[n1][m1]

for i in range(n, -1, -1):
    for j in range(m, -1, -1):
        if i == n and j == m:
            dp[i][j] = lcs(a, b)
