import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]  # 1-indexed
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)

    # Find connected components using DFS or BFS
    visited = [False] * (n + 1)
    result = 'YES'

    for start in range(1, n + 1):
        if not visited[start]:
            # DFS to find component
            stack = [start]
            visited[start] = True
            component = []
            while stack:
                node = stack.pop()
                component.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

            # Check if this component is a clique
            k = len(component)
            if k > 1:
                # Each node should have degree k - 1 within the component
                # Check all nodes in component
                for node in component:
                    # Count how many friends are in component
                    cnt = 0
                    for friend in adj[node]:
                        if friend in component:
                            cnt += 1
                    if cnt != k - 1:
                        result = 'NO'
                        break
                if result == 'NO':
                    break

    print(result)

if __name__ == '__main__':
    solve()
