import heapq

def solve():
    n, k = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    # Priority queue: (current_string, i, j, cost)
    pq = []
    # Start at (0,0) with string grid[0][0] and cost 0
    heapq.heappush(pq, (grid[0][0], 0, 0, 0))

    # Track minimum cost to reach each position with a specific string
    # min_cost[(i,j)] = dictionary of {string: cost}
    min_cost = {(0, 0): {grid[0][0]: 0}}

    while pq:
        s, i, j, cost = heapq.heappop(pq)

        # If we reach the destination
        if i == n - 1 and j == n - 1:
            print(s)
            return

        # Generate next states
        for di, dj in [(0, 1), (1, 0)]:
            ni, nj = i + di, j + dj

            if 0 <= ni < n and 0 <= nj < n:
                # Calculate the new string
                new_s = s + grid[ni][nj]

                # Calculate the new cost
                new_cost = cost
                if grid[ni][nj] != grid[i][j]:
                    new_cost += 1

                # Check if we can improve upon reaching (ni, nj) with new_s
                if (ni, nj) not in min_cost:
                    min_cost[(ni, nj)] = {new_s: new_cost}
                    heapq.heappush(pq, (new_s, ni, nj, new_cost))
                elif new_s not in min_cost[(ni, nj)] or new_cost < min_cost[(ni, nj)][new_s]:
                    min_cost[(ni, nj)][new_s] = new_cost
                    heapq.heappush(pq, (new_s, ni, nj, new_cost))

    print("No path found")

solve()
