def solve():
    s = input().strip()

    if s[0] == '1':
        print(-1)
        return

    # Greedily build zebras
    zebras = []
    current_zebra = []

    for i, ch in enumerate(s):
        if ch == '0':
            if not current_zebra or s[i-1] != '0':
                # Start a new zebra or continue the current one (if it's the first character)
                current_zebra.append(i + 1)
            else:
                # Previous character was 0, need to start a new zebra
                if current_zebra:
                    zebras.append(current_zebra)
                    current_zebra = [i + 1]
        else:
            # ch == '1'
            if current_zebra:
                # We expect a 0, so we can add
                current_zebra.append(i + 1)

        # Check if we can complete the zebra
        if current_zebra and current_zebra[-1] == i + 1 and i + 1 == len(s):
            zebras.append(current_zebra)
            current_zebra = []

    if current_zebra:
        # Incomplete zebra at the end
        print(-1)
        return

    print(len(zebras))
    for zebra in zebras:
        print(len(zebra), end=' ')
        print(' '.join(map(str, zebra)))

solve()
