    max_edge = [0] * (n + 1)

    for _ in range(n - 1):
        a, b, c = map(int, input().split())
        tree[a].append((b, c))
        tree[b].append((a, c))
        max_edge[a] = max(max_edge[a], c)
        max_edge[b] = max(max_edge[b], c)

    x = [0] + [int(input()) for _ in range(n)]

    # dp[u][k] = maximum value when ending at u with k nodes used
    dp = [[-1] * (n + 1) for _ in range(n + 1)]

    # Base case: start at each node with 1 node used
    for i in range(1, n + 1):
        dp[i][1] = 0

    # Fill dp table
    for k in range(2, n + 1):
        for u in range(1, n + 1):
            if dp[u][k] == -1:
                continue

            for v, w in tree[u]:
                if dp[v][k - 1] != -1:
                    dp[u][k] = max(dp[u][k], dp[v][k - 1] + w)

    # Find maximum value
    ans = 0
    for i in range(1, n + 1):
        ans = max(ans, dp[i][n])

    print(ans)

