from collections import Counter
freq = Counter(letters)

# Function to distribute letters to form a word of length l
# For large words, we want as many large letters as possible
# For small words, we want as many small letters as possible

def distribute_large(l, freq):
    word = []
    # Use as many large letters as possible
    for c in reversed(string.ascii_lowercase):
        while freq[c] > 0 and len(word) < l:
            word.append(c)
            freq[c] -= 1
    return ''.join(word)

def distribute_small(l, freq):
    word = []
    # Use as many small letters as possible
    for c in string.ascii_lowercase:
        while freq[c] > 0 and len(word) < l:
            word.append(c)
            freq[c] -= 1
    return ''.join(word)

# For the first k-1 words, make them as large as possible
words = []
for _ in range(k-1):
    words.append(distribute_large(l, freq.copy()))

# For the k-th word, make it as small as possible
words.append(distribute_small(l, freq.copy()))

# For the remaining words, make them as large as possible
for _ in range(n - k):
    words.append(distribute_large(l, freq.copy()))

# Output the words
for word in words:
