letters = input().strip()

# Count letter frequencies
from collections import Counter
freq = Counter(letters)

# Function to distribute letters to form a word of length l
# Using small letters first

def distribute_small(l, freq):
    word = []
    for c in string.ascii_lowercase:
        while freq[c] > 0 and len(word) < l:
            word.append(c)
            freq[c] -= 1
    return ''.join(word)

# Function to distribute letters to form a word of length l
# Using large letters first

def distribute_large(l, freq):
    word = []
    for c in reversed(string.ascii_lowercase):
        while freq[c] > 0 and len(word) < l:
            word.append(c)
            freq[c] -= 1
    return ''.join(word)

# Try to form the k-th word as small as possible, then distribute remaining
words = []
remaining_freq = freq.copy()

# For the k-th word, use as many small letters as possible
if k - 1 < n:
    words.append(distribute_small(l, remaining_freq))

# For the other words, distribute remaining letters
for i in range(n):
    if i == k - 1:
        continue

    # If we've used up all letters, break
    if sum(freq.values()) == 0:
        break

    # Distribute using large letters
    word = []
    for c in reversed(string.ascii_lowercase):
        while freq[c] > 0 and len(word) < l:
            word.append(c)
            freq[c] -= 1
    words.append(''.join(word))

# Sort the words lexicographically
words.sort()

# Output the words
for word in words:
    print(word)
