import sys
import math

def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    sqrt_n = int(math.sqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False

    return True

def is_t_prime(x):
    """Check if x is a T-prime (has exactly 3 distinct divisors)."""
    sqrt_x = int(math.sqrt(x))
    if sqrt_x * sqrt_x != x:
        return False  # Not a perfect square

    return is_prime(sqrt_x)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    numbers = list(map(int, data[1:1+n]))

    for x in numbers:
        if is_t_prime(x):
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    main()
"}

