def solve():
    n = int(input())
    sequence = list(map(int, input().split()))

    # Count frequency of each element
    freq = {}
    for num in sequence:
        freq[num] = freq.get(num, 0) + 1

    # Check if sequence is already good
    def is_good():
        for num in freq:
            # Try all powers of two up to 2^31
            for k in range(0, 32):  # 2^31 is the largest power of two we need to consider
                target = 1 << k
                pair = target - num
                # Check if there's another element that can pair with num
                if freq.get(pair, 0) > 0 and (pair != num or freq[num] > 1):
                    break
            else:
                # No power of two found for this element
                return False
        return True

    if is_good():
        print(0)
        return

    # Try removing elements until we find a good sequence
    # Let's try removing at most 5 elements
    # For each number of elements to remove, try removing that many elements
    for remove_count in range(1, 6):
        # Try all combinations of removing 'remove_count' elements
        # This is too slow for n=120000, but let's try for small remove_count
        if remove_count < n:
            # Try removing each element once
            for i in range(n):
                temp = sequence[:i] + sequence[i+1:]
                if is_good(temp):
