import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        W = int(data[idx + 1])
        idx += 2

        widths = list(map(int, data[idx:idx + n]))
        idx += n

        # Count how many rectangles of each width (power of 2)
        count = {}
        for w in widths:
            count[w] = count.get(w, 0) + 1

        # Sort widths in decreasing order
        widths_sorted = sorted(count.keys(), reverse=True)

        height = 0
        current_row_width = 0

        for w in widths_sorted:
            # How many rectangles of width w can we fit in the current row?
            max_in_row = count[w]

            # Try to fit as many as possible
            for i in range(1, max_in_row + 1):
                if current_row_width + i * w <= W:
                    continue
                else:
                    # Can't fit i rectangles, so we need i-1 rectangles in this row
                    height += 1
                    current_row_width = i * w - W
                    # Now try to fit the remaining rectangles
                    for j in range(i, max_in_row + 1):
                        if current_row_width + j * w <= W:
                            current_row_width += j * w
                            break
                    else:
                        # Can't fit any more
                        height += 1
                        current_row_width = 0
                    break
            else:
                # All max_in_row rectangles fit
                current_row_width += max_in_row * w

        # If we have any remaining width in the last row, we need at least one more row
        if current_row_width > 0:
            height += 1

        print(height)

if __name__ == "__main__":
    solve()
