import sys
import math

def gcd(a, b):
    return math.gcd(a, b)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    result = []
    insertions = 0

    for i in range(n):
        result.append(arr[i])
        if i < n - 1:
            a = arr[i]
            b = arr[i+1]
            if gcd(a, b) > 1:
                result.append(1)  # Insert 1 as a co-prime number
                insertions += 1

    print(insertions)
    print(' '.join(map(str, result)))

solve()
