def is_prime(n, spf):
    """Check if n is prime using the smallest prime factor array."""
    if n < 2:
        return False
    while n > 1:
        p = spf[n]
        if p == n:
            return True  # n is prime
        n //= p
        if n % p == 0:
            return False  # has a square factor
    return True

def solve():
    # Precompute smallest prime factors up to 10^6
    max_prime = 10**6
    spf = list(range(max_prime + 1))
    for i in range(2, int(max_prime**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i*i, max_prime + 1, i):
                if spf[j] == j:
                    spf[j] = i

    n = int(input())
    nums = list(map(int, input().split()))

    for x in nums:
        # Check if x is a perfect square
        root = int(x**0.5)
        if root * root != x:
            print("NO")
        else:
            # Check if the root is prime
            if is_prime(root, spf):
                print("YES")
            else:
                print("NO")

solve()
