import sys

def is_zebra(subsequence, s):
    """Check if a subsequence is a valid zebra"""
    # Extract the characters in order
    chars = [s[i-1] for i in subsequence]

    # A zebra must start and end with '0'
    if chars[0] != '0' or chars[-1] != '0':
        return False

    # Check if it alternates properly
    for i in range(1, len(chars)):
        if i % 2 == 0 and chars[i] != '1':
            return False
        if i % 2 == 1 and chars[i] != '0':
            return False

    return True

def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    # Try to form a solution
    # Start with the first day as a zebra on its own
    # Then try to form the rest

    # Create a list of indices for each day
    day_indices = list(range(1, n + 1))

    # Try to form a zebra starting from day 1
    result = []

    # First day as a zebra on its own
    if s[0] == '0':
        result.append([1])
        day_indices.remove(1)

    # Try to form a zebra with the remaining days
    for i in range(1, len(day_indices)):
        # Try to form a zebra
        current_subsequence = [day_indices[i]]

        # Find a matching day
        for j in range(i + 1, len(day_indices)):
            if j - i == 1 and s[day_indices[j]-1] == '1':
                current_subsequence.append(day_indices[j])

            elif j - i == 2 and s[day_indices[j]-1] == '0':
                current_subsequence.append(day_indices[j])

            elif j - i == 3 and s[day_indices[j]-1] == '1':
                current_subsequence.append(day_indices[j])

            elif j - i == 4 and s[day_indices[j]-1] == '0':
                current_subsequence.append(day_indices[j])

            # Check if we've formed a valid zebra
            if len(current_subsequence) >= 3:
                if is_zebra(current_subsequence, s):
                    result.append(current_subsequence)
                    # Remove these days from day_indices
                    for idx in current_subsequence:
                        day_indices.remove(idx)
                    break

    # Check if we used all days
    if len(day_indices) > 0:
        return -1

    # Output the result
    print(len(result))
