    # i ranges from 0 to n, j ranges from 0 to m
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if A[i] == B[j]:
                dp[i+1][j+1] = dp[i][j] + 1
            else:
                dp[i+1][j+1] = max(dp[i][j+1], dp[i+1][j])

    max_score = -float('inf')

    # Try all possible substring lengths
    for l in range(1, min(n, m) + 1):
        # For each possible starting position in A
        for i in range(n - l + 1):
            # For each possible starting position in B
            for j in range(m - l + 1):
                # Calculate LCS of substrings A[i:i+l] and B[j:j+l]
                lcs = dp[i+l][j+l] - dp[i][j+l] - dp[i+l][j] + dp[i][j]

                # Calculate similarity score
                score = 4 * lcs - 2 * l

                # Update maximum
                if score > max_score:
                    max_score = score

    print(max_score)

