def can_illuminate(n, blocked, l):
    """Check if we can illuminate [0, n] using lamps of power l"""
    # First, check if position 0 can be covered
    # A lamp at position p covers [p, p+l]. For this to cover 0, we need 0 ≤ p ≤ p+l
    # Which is always true for p ≥ 0, so we just need a lamp at some position ≥ 0
    # But position 0 might be blocked, so we need a lamp at some other position

    # Find the rightmost position we can place a lamp to cover 0
    max_pos = min(n, 0 + l)
    rightmost = -1
    for pos in range(max_pos, 0 - 1, -1):
        if pos not in blocked:
            rightmost = pos
            break

    if rightmost == -1:
        return False

    # Now cover from rightmost to n
    current = rightmost
    while current < n:
        max_pos = min(n, current + l)
        rightmost = -1
        for pos in range(max_pos, current - 1, -1):
            if pos not in blocked:
                # Check if this lamp actually covers current
                if current <= pos + l:
