def get_prime_factors(n):
    """Return a set of prime factors of n"""
    factors = set()
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n //= 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n //= i
        i += 2
    if n > 1:
        factors.add(n)
    return factors

def main():
    import sys
    input = sys.stdin.read().split()

    if not input:
        return

    n = int(input[0])
    m = int(input[1])

    # Prime factors for each number
    prime_factors = [set() for _ in range(n + 1)]
    for i in range(1, n + 1):
        prime_factors[i] = get_prime_factors(i)

    # Map from prime to list of colliders with that prime as a factor
    prime_to_colliders = {}
    for i in range(1, n + 1):
        for p in prime_factors[i]:
            if p not in prime_to_colliders:
                prime_to_colliders[p] = []
            prime_to_colliders[p].append(i)

    # Activated status of each collider
    activated = [False] * (n + 1)

    out_lines = []

    idx = 2
    for _ in range(m):
        req = input[idx]
        i = int(input[idx + 1])
        idx += 2

        if req == '+':
            if activated[i]:
                out_lines.append("Already on")
            else:
                # Check for conflicts
                conflict = None
                for p in prime_factors[i]:
                    # Check if any collider with this prime factor is activated
                    for j in prime_to_colliders.get(p, []):
                        if activated[j]:
                            conflict = j
                            break
                    if conflict:
                        break

                if conflict:
                    out_lines.append(f"Conflict with {conflict}")
                else:
                    out_lines.append("Success")
                    activated[i] = True
        else:  # req == '-'
            if not activated[i]:
                out_lines.append("Already off")
            else:
                out_lines.append("Success")
                activated[i] = False

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
