    n = int(next(it))
    m = int(next(it))

    # Store participants by region
    regions = [[] for _ in range(m + 1)]  # 1-indexed

    for _ in range(n):
        surname = next(it)
        region = int(next(it))
        score = int(next(it))
        regions[region].append((surname, score))

    # Process each region
    for region in range(1, m + 1):
        participants = regions[region]

        # Sort by score descending, then by surname ascending
        participants.sort(key=lambda x: (-x[1], x[0]))

        # If only 2 participants, they form the team
        if len(participants) == 2:
