        # Find other hostnames that match this one
        for other_hostname, other_urls in hostname_to_urls.items():
            if hostname == other_hostname:
                continue

            # Check if sets are equal
            if set(urls) == set(other_urls):
                # Create a frozenset for the group
                group = frozenset([hostname, other_hostname])
