import sys

def parse_url(url):
    """Parse a URL into hostname and path"""
    # Split on '://' to get the host part
    parts = url.split('://', 1)
    if len(parts) < 2:
        return None, None

    # The second part should be the host and path
    host_part = parts[1]

    # Split on '/' to get hostname and path
    segments = host_part.split('/', 1)
    if len(segments) < 2:
        return None, None

    hostname = segments[0]
    path = segments[1] if len(segments) > 1 else ""

    return hostname, path

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0])
    urls = data[1:n+1]

    # Map from hostname to set of paths
    hostname_to_paths = {}

    for url in urls:
        hostname, path = parse_url(url)
        if hostname is None or path is None:
            continue

        if hostname not in hostname_to_paths:
            hostname_to_paths[hostname] = set()

        hostname_to_paths[hostname].add(path)

    # Group hostnames by their path sets
    path_set_to_hostnames = {}

    for hostname, paths in hostname_to_paths.items():
        # Use a frozenset as a key
        if len(paths) == 0:
            key = frozenset()
        else:
            key = frozenset(paths)

        if key not in path_set_to_hostnames:
            path_set_to_hostnames[key] = set()

        path_set_to_hostnames[key].add(hostname)

    # Find groups with more than one hostname
    groups = []
    for hostnames in path_set_to_hostnames.values():
        if len(hostnames) > 1:
            groups.append(sorted(hostnames))

    # Output the result
    # The problem expects full URLs, not just hostnames
    # So we need to collect all URLs that match any of the hostnames in a group
    # But we should group them by the hostname order
    groups_with_urls = []

    for hostnames in path_set_to_hostnames.values():
        if len(hostnames) > 1:
            # Find all URLs that match any of these hostnames
            matching_urls = set()
            for hostname in hostnames:
                for url in urls:
                    if hostname in url:
                        matching_urls.add(url)

            # Sort by hostname lexicographically
            # But we need to make sure we get the correct order as expected
            # Let's try a different approach: group by hostname first, then by URL order

            # Create a mapping from hostname to list of URLs
            hostname_to_urls = {}
            for url in urls:
                hostname, _ = parse_url(url)
                if hostname not in hostname_to_urls:
                    hostname_to_urls[hostname] = []
                hostname_to_urls[hostname].append(url)

            # Sort by hostname lexicographically
            # For each hostname in the group, add its URLs in the order they appeared
            sorted_hostnames = sorted(hostnames)
            group_urls = []
            for hostname in sorted_hostnames:
                group_urls.extend(hostname_to_urls[hostname])

            groups_with_urls.append(group_urls)

    print(len(groups_with_urls))
    for group in groups_with_urls:
        print(' '.join(group))

