C, Hr, Hb, Wr, Wb = map(int, input().split())

# Calculate the maximum number of candies we could possibly eat
# We need to bound by the type with the lower ratio of joy to weight
if Hr * Wb > Hb * Wr:
    # Red candy has higher joy/weight ratio
    max_candies = min(C // Wr, C // Wb)
else:
    # Blue candy has higher joy/weight ratio
    max_candies = min(C // Hr, C // Hb)

max_joy = 0

# Try all possible numbers of the candy with lower joy/weight ratio
for x in range(max_candies + 1):
    if Hr * Wb > Hb * Wr:
        remaining_weight = C - x * Wr
    else:
        remaining_weight = C - x * Wb

    if remaining_weight < 0:
        break

    if Hr * Wb > Hb * Wr:
        y = remaining_weight // Wb
        joy = x * Hr + y * Hb
    else:
        x = remaining_weight // Wr
        joy = x * Hr + y * Hb

    if joy > max_joy:
        max_joy = joy

print(max_joy)
"}

