import math

def gcd(a, b):
    return math.gcd(a, b)

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    result = []
    insertions = 0

    for i in range(n - 1):
        # Check if current pair is co-prime
        if gcd(a[i], a[i + 1]) == 1:
            result.append(a[i])
        else:
            # Need to insert a number between them
            insertions += 1
            # Find a number that is co-prime with both
            for candidate in range(2, 100):
                if gcd(a[i], candidate) == 1 and gcd(candidate, a[i + 1]) == 1:
                    result.append(a[i])
                    result.append(candidate)
                    break

    # Add the last element
    result.append(a[-1])

    print(insertions)
    print(' '.join(map(str, result)))

solve()
"}

