import sys

# List of primes up to 10^5 for quick access
# We'll generate them using the Sieve of Eratosthenes

# For this problem, we can just use the Sieve of Eratosthenes

def solve() -> None:
    n = int(sys.stdin.readline())

    # Array to store color for each number
    color = [0] * (n + 1)  # 0-index unused

    # Sieve of Eratosthenes to find primes
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    # Assign colors
    current_color = 1
    for num in range(2, n + 1):
        if is_prime[num]:
            color[num] = current_color
            current_color += 1
        else:
            color[num] = 1

    # Output the colors for 2 to n
    output = [str(color[i]) for i in range(2, n + 1)]
    print(' '.join(output))

if __name__ == "__main__":
    solve()
"}

