def solve():
    n, m = map(int, input().split())

    # For each city, store which roads connect to it
    roads_from = [[] for _ in range(n + 1)]  # roads_from[city] = list of (other_city, road_initial_state)

    for _ in range(m):
        a, b, c = map(int, input().split())
        roads_from[a].append((b, c))
        roads_from[b].append((a, c))

    # Try both possibilities for city 1
    for start_val in [0, 1]:
        # Assign values to cities
        x = [None] * (n + 1)
        x[1] = start_val
        contradiction = False

        # Propagate through the graph
        for i in range(1, n + 1):
            if x[i] is None:
                continue

            for (neighbor, c) in roads_from[i]:
                if x[neighbor] is None:
                    x[neighbor] = x[i] ^ c
                else:
                    # Check if we get a contradiction
                    if x[neighbor] != (x[i] ^ c):
                        contradiction = True
                        break
            if contradiction:
                break

        if not contradiction:
            # We have a valid assignment, now output the solution
            # Each city with value 1 means we need to flip it
            cities_to_flip = [i for i in range(1, n + 1) if x[i] == 1]

            print(len(cities_to_flip))
            print(' '.join(map(str, cities_to_flip)))
            return

    # If neither possibility works
    print("Impossible")

