from itertools import combinations

def solve():
    n = int(input())
    words = []
    for _ in range(n):
        words.append(input().strip())

    # For each word, store which letters it uses
    word_letters = []
    for word in words:
        letters = set(word)
        word_letters.append(letters)

    # Try all pairs of letters (including same letter pairs)
    max_length = 0

    # Try all combinations of 2 letters
    for c1, c2 in combinations(range(26), 2):
        letter_set = {chr(ord('a') + c1), chr(ord('a') + c2)}
        total = 0
        for letters in word_letters:
            # Check if all letters in this word are in the letter set
            if letters.issubset(letter_set):
                total += len(words[word_letters.index(letters)])
